import React from "react";
import Layout from "../components/layout";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { UserProfile } from "../interfaces";
import data from "../data/data.json";
import { graphql } from "gatsby";
import images from "../images";
import { FaSquarePhone } from "react-icons/fa6";
import { MdEmail } from "react-icons/md";
import ContactForm from "../components/contactForm";
import { ImFacebook2, ImLinkedin, ImLocation } from "react-icons/im";
import { SiInstagram } from "react-icons/si";

const WhatWeDo: React.FC = () => {
  const { t } = useTranslation();
  const userData: UserProfile = data;

  function formatPhoneNumber(phoneNumber: string) {
    const cleanedPhoneNumber = phoneNumber.replace(/\D+/g, "");
    if (cleanedPhoneNumber.startsWith("1")) {
      return `+1 ${cleanedPhoneNumber.slice(1, 4)} ${cleanedPhoneNumber.slice(
        4,
        7
      )} ${cleanedPhoneNumber.slice(7, 12)}`;
    } else {
      return cleanedPhoneNumber;
    }
  }

  return (
    <Layout data={userData}>
      <div className="w-full sm:w-3/4 my-16 mx-auto">
        <h1 className="text-4xl text-center mb-4">{t("readyToStart.title")}</h1>
        <h3
          className="text-xl text-center mb-4"
          dangerouslySetInnerHTML={{
            __html: t("readyToStart.description") ?? "",
          }}
        />
      </div>

      <div className="w-full px-4 sm:px-0">
        <ContactForm />
      </div>

      <h2 className="text-xl sm:text-3xl uppercase text-center text-secondary font-bold mt-8">
        {t("form.financing")}
      </h2>
      <div className="max-w-44 mx-auto my-8">
        <a
          href="https://www.financeit.ca/s/h7lnzQ"
          target="_blank"
          className="bg-white text-center border border-secondary rounded-lg text-secondary inline-block justify-center px-4 py-2"
        >
          {t("form.financingBtn")}{" "}
          <img src={images.financeit.src} alt={images.financeit.alt} />
        </a>
      </div>

      <div className="w-full px-4 flex flex-col sm:flex-row my-16 pb-0 justify-center">
        <div className="w-full sm:w-1/2 h-[500px]  mb-4 sm:mb-0">
          <iframe
            className="w-full h-full"
            src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d2799.76007872942!2d-73.49265032356459!3d45.434337535430515!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4cc90fa8e63c9c03%3A0xd81f311632cbabf6!2s9270%20Rue%20Riverin%2C%20Brossard%2C%20QC%20J4X%203A4!5e0!3m2!1ses!2sca!4v1748139868880!5m2!1ses!2sca"
            loading="lazy"
          ></iframe>
        </div>

        <div className="w-full sm:w-1/4 sm:h-auto mb-4 sm:mb-0 px-4 text-xl">
          <h2 className="text-4xl mb-5">{userData.name}</h2>

          {/* Teléfono */}
          <a
            className="flex items-center gap-2 mb-4"
            href={`tel:${userData.phone}`}
          >
            <FaSquarePhone className="text-secondary min-w-[1.5rem]" />
            <span>{formatPhoneNumber(userData.phone)}</span>
          </a>

          {/* Dirección */}
          <div className="flex items-start gap-2 mb-4">
            <ImLocation className="text-secondary mt-1 min-w-[1.5rem]" />
            <div>
              <p>{userData.address}</p>
              <p>
                {userData.city}, {userData.province}, {userData.postalCode}
              </p>
            </div>
          </div>

          {/* Email */}
          <a
            className="flex items-center gap-2 mb-5"
            href={`mailto:${userData.email}`}
          >
            <MdEmail className="text-secondary min-w-[1.5rem]" />
            <span>{userData.email}</span>
          </a>
        </div>
      </div>

      <div className="text-secondary justify-center social mb-16">
        <a href={userData.instagram} target="_blank" rel="noreferrer">
          <SiInstagram />
        </a>
        <a href={userData.facebook} target="_blank" rel="noreferrer">
          <ImFacebook2 />
        </a>
        <a href={userData.linkedin} target="_blank" rel="noreferrer">
          <ImLinkedin />
        </a>
      </div>
    </Layout>
  );
};
export default WhatWeDo;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  row: "flex flex-row gap-2 items-center",
};